const navItems=['Обзор','Проекты','Временная шкала','Финансовая сводка','Калькулятор сделки','Справочники','Импорт и экспорт','Настройки'];
const baseDeals=[
 {id:'ТКП-2026-001',title:'Поставка оборудования',customer:'ООО «Ромашка»',manager:'Иванов Иван',status:'В работе',amount:1800000,contract:'2026-09-10',shipment:'2026-10-02',payment:'2026-10-10',close:'2026-10-20',actualPayment:0,direction:'Промышленность',history:[]},
 {id:'ТКП-2026-002',title:'Закрытая поставка',customer:'ООО «Путь»',manager:'Иванова Вера',status:'Закрыто',amount:750000,contract:'2026-08-08',shipment:'2026-09-03',payment:'2026-09-05',close:'2026-09-18',actualShipment:'2026-09-04',actualPaymentDate:'2026-09-06',actualPayment:750000,actualClose:'2026-09-19',direction:'Поставка',history:[]}
];
const probability={'Получен лид':.1,'Создано ТКП':.3,'Передано на согласование':.5,'Подписано':1,'В работе':1,'Закрыто':1};
let state={page:'Обзор',deals:structuredClone(baseDeals),userDeal:null,period:'Год',customers:[{name:'ООО «Ромашка»',manager:'Иванов Иван',phone:'+7 900 000 00 00',email:'demo@ex.test'},{name:'ООО «Путь»',manager:'Иванова Вера',phone:'+7 901 000 00 00',email:'demo@ex.test'}],userCustomer:null,columns:['id','customer','manager','status','probability','amount','contract','shipment','attention'],projectFilter:'active'};
const $=s=>document.querySelector(s), money=n=>new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB',maximumFractionDigits:0}).format(n||0), fmt=d=>d?new Date(d+'T00:00').toLocaleDateString('ru-RU'): '—';
function persist(){sessionStorage.setItem('tkp-demo',JSON.stringify(state))}function restore(){try{const x=JSON.parse(sessionStorage.getItem('tkp-demo'));if(x&&x.customers)state=x}catch{}}restore();
if(!state.periodMode)state.periodMode='Текущий год';
function overdue(d){return d&&d<'2026-09-19'} function isOverdue(d){return overdue(d.shipment)||overdue(d.payment)&&d.actualPayment<d.amount||overdue(d.close)}
function nav(){ $('#nav').innerHTML=navItems.map(x=>`<button class="${x===state.page?'active':''}" data-page="${x}">${x}</button>`).join('');$('#nav').onclick=e=>{let p=e.target.dataset.page;if(p){state.page=p;render()}}}
function period(){return `<div class="period"><b>ПЕРИОД ПЛАНИРОВАНИЯ</b><span>01 янв. 2026 — 31 дек. 2026</span>${['Месяц','Квартал','Год','Следующий год'].map(x=>`<button class="${state.period===x?'active':''}" onclick="state.period='${x}';render()">${x==='Год'?'Текущий год':x}</button>`).join('')}</div>`}
function banner(){return `<div class="notice"><span>🛡 <b>Пора создать резервную копию</b><small> Данные демонстрационной сессии исчезнут после закрытия вкладки.</small></span><button onclick="backup()" class="primary">Создать копию</button></div>`}
function kpis(){let ds=state.deals,active=ds.filter(x=>x.status!=='Закрыто'),forecast=ds.filter(x=>x.contract?.startsWith('2026')).reduce((s,x)=>s+x.amount*probability[x.status],0),rev=ds.filter(x=>x.shipment?.startsWith('2026')).reduce((s,x)=>s+x.amount,0),cash=ds.filter(x=>x.payment?.startsWith('2026')).reduce((s,x)=>s+x.amount,0);return `<div class="cards"><div class="card"><span class="label">Активные проекты</span><strong>${active.length}</strong><small>Все проекты в работе</small></div><div class="card"><span class="label">Прогноз договоров</span><strong>${money(forecast)}</strong><small>По плановой дате договора</small></div><div class="card"><span class="label">Плановая выручка</span><strong>${money(rev)}</strong><small>По отгрузке</small></div><div class="card"><span class="label">Денежный поток</span><strong>${money(cash)}</strong><small>Ожидаемые поступления</small></div></div>`}
function dealRows(ds=state.deals){return ds.map(d=>`<tr class="${d.status==='Закрыто'?'closed-row':'active-row'}"><td><b>${d.id}</b><br><small>${d.title}</small></td><td>${d.customer}</td><td>${d.manager}</td><td><span class="badge ${d.status==='Закрыто'?'status-closed':'status-active'}">${d.status}</span></td><td>${Math.round(probability[d.status]*100)}%</td><td><b>${money(d.amount)}</b></td><td>${fmt(d.contract)}</td><td>${fmt(d.shipment)}</td><td>${isOverdue(d)?'<span class="badge danger">⚠ Просрочено</span>':'—'}</td><td><button onclick="openDeal('${d.id}')">⋯</button></td></tr>`).join('')}
function dealTable(ds){let c=state.columns||['id','customer','manager','status','probability','amount','contract','shipment','attention'],heads={id:'Номер ТКП',customer:'Заказчик',manager:'Руководитель',status:'Статус',title:'Описание',direction:'Направление',probability:'Вероятность',amount:'Без НДС',contract:'Договор, план',shipment:'Ближайшее событие',attention:'Внимание'},val=(d,k)=>({id:`<b>${d.id}</b><br><small>${d.title}</small>`,customer:d.customer,manager:d.manager,status:`<span class="badge ${d.status==='Закрыто'?'status-closed':'status-active'}">${d.status}</span>`,title:d.title,direction:d.direction,probability:`${Math.round(probability[d.status]*100)}%`,amount:`<b>${money(d.amount)}</b>`,contract:fmt(d.contract),shipment:fmt(d.shipment),attention:isOverdue(d)?'<span class="badge danger">⚠ Просрочено</span>':'—'})[k];return `<div class="panel"><table class="table"><thead><tr>${c.map(k=>`<th>${heads[k]}</th>`).join('')}<th></th></tr></thead><tbody>${ds.map(d=>`<tr class="${d.status==='Закрыто'?'closed-row':'active-row'}">${c.map(k=>`<td>${val(d,k)}</td>`).join('')}<td><button onclick="openDeal('${d.id}')">⋯</button></td></tr>`).join('')}</tbody></table></div>`}
function overview(){let alerts=state.deals.filter(isOverdue);return `<div class="wrap"><h1>Обзор</h1><p class="sub">Ключевые показатели и ближайшие события.</p>${banner()}${period()}${kpis()}<div class="grid2"><div>${dealTable(state.deals.filter(x=>x.status!=='Закрыто'))}</div><div class="panel"><h3>Требует внимания</h3><ul class="kpi-list">${alerts.length?alerts.map(x=>`<li>⚠ <b>${x.id}</b><br><small>Просрочена плановая дата</small></li>`).join(''):'<li>Нет проблемных сделок</li>'}</ul></div></div></div>`}
function projects(){let ds=state.deals.filter(d=>state.projectFilter==='active'?!d.archived&&!d.draft:state.projectFilter==='draft'?d.draft:d.archived);return `<div class="wrap"><h1>Все проекты</h1><p class="sub">Красная полоса — активный проект; зелёная — закрытый.</p>${banner()}<div class="toolbar"><button class="${state.projectFilter==='active'?'active':''}" onclick="state.projectFilter='active';render()">Все активные</button><button class="${state.projectFilter==='draft'?'active':''}" onclick="state.projectFilter='draft';render()">Черновики</button><button class="${state.projectFilter==='archive'?'active':''}" onclick="state.projectFilter='archive';render()">Архив</button><input id="project-search" placeholder="⌕ Поиск по сделкам"><button onclick="columnInfo()">▥ Колонки</button><button class="primary" onclick="showDealForm()">＋ Новая сделка</button></div>${dealTable(ds)}</div>`}
function timeline(){let months=['Сентябрь','Октябрь','Ноябрь','Декабрь'], cell=(d,m)=>{let items=[];[['contract','Договор'],['payment','Финальный платёж'],['shipment','Отгрузка'],['close','Закрытие']].forEach(([k,n])=>{if(d[k]?.slice(5,7)==m)items.push(`<div class="event ${overdue(d[k])?'overdue':''}">${n}<br>${fmt(d[k])}</div>`)});return items.join('')};return `<div class="wrap"><h1>Месячная временная шкала</h1><p class="sub">Проекты по ключевым плановым датам.</p>${banner()}${period()}<div class="toolbar"><input placeholder="⌕ Номер, заказчик, описание"><select><option>Все руководители</option></select><select><option>Все статусы</option></select><button>‹</button><button>Сегодня</button><button>›</button></div><div class="panel"><div class="timeline"><b>ПРОЕКТ И ОПИСАНИЕ</b>${months.map(x=>`<b>${x} 2026</b>`).join('')}${state.deals.map(d=>`<div><b>${d.id}</b><br><small>${d.title}</small></div>${[9,10,11,12].map(m=>`<div>${cell(d,String(m).padStart(2,'0'))}</div>`).join('')}`).join('')}</div></div></div>`}
function finance(){let months=['Янв','Фев','Мар','Апр','Май','Июн','Июл','Авг','Сен','Окт','Ноя','Дек'], sum=(key,month,weighted=false)=>state.deals.filter(d=>d[key]?.slice(5,7)===String(month).padStart(2,'0')).reduce((s,d)=>s+d.amount*(weighted?probability[d.status]:1),0);return `<div class="wrap"><h1>Договоры, выручка и денежный поток</h1><p class="sub">Помесячные финансовые показатели.</p>${banner()}${period()}${kpis()}<div class="panel"><h3>Динамика по месяцам</h3><div class="chart">${months.map((x,i)=>{let v=sum('shipment',i+1);return `<div class="bar" style="height:${Math.max(3,v/25000)}px" data-month="${x}" title="Выручка: ${money(v)}"></div>`}).join('')}</div></div><div class="panel"><h3>Помесячная сводка</h3><table class="table"><thead><tr><th>Месяц</th><th>Прогноз договоров</th><th>Плановая выручка</th><th>Денежный поток</th><th>Неполный график</th></tr></thead><tbody>${months.map((x,i)=>`<tr><td><b>${x} 2026</b></td><td>${money(sum('contract',i+1,true))}</td><td>${money(sum('shipment',i+1))}</td><td>${money(sum('payment',i+1))}</td><td>${state.deals.filter(d=>d.payment?.slice(5,7)===String(i+1).padStart(2,'0')&&d.actualPayment<d.amount&&overdue(d.payment)).length||'—'}</td></tr>`).join('')}</tbody></table></div><h2>Отчёты</h2><div class="report-cards"><div class="card"><b>Воронка</b><p>${state.deals.map(d=>d.status).filter((x,i,a)=>a.indexOf(x)===i).join(' · ')}</p></div><div class="card"><b>Просроченная дебиторка</b><strong>${money(state.deals.filter(d=>overdue(d.payment)).reduce((s,d)=>s+d.amount-d.actualPayment,0))}</strong></div><div class="card"><b>Эффективность менеджеров</b><p>Анна Демина: ${money(state.deals.filter(d=>d.manager==='Анна Демина').reduce((s,d)=>s+d.amount,0))}</p></div></div></div>`}
function calculator(){return `<div class="wrap"><h1>Калькулятор сделки: скидка и премия</h1><p class="sub">Все суммы указываются в рублях, без НДС.</p>${banner()}<div class="grid2"><div class="panel"><h3>Ввод данных</h3><div class="wrap"><div class="form-grid"><div class="field"><label>Базовая цена</label><input id="price" type="number" value="1000000"></div><div class="field"><label>Себестоимость оборудования</label><input id="cost" type="number" value="650000"></div><div class="field"><label>ВЭД, %</label><input id="ved" type="number" value="0"></div><div class="field"><label>Доставка</label><input id="delivery" type="number" value="0"></div><div class="field"><label>Монтаж</label><input id="install" type="number" value="0"></div><div class="field"><label>Минимальная маржа, %</label><input id="minmargin" type="number" value="26"></div><div class="field"><label>Предлагаемая скидка, %</label><input id="discount" type="number" value="0"></div></div><div class="modal-actions"><button class="primary" onclick="calc()">Рассчитать показатели</button></div></div></div><div class="panel"><h3>Результаты анализа</h3><div class="wrap" id="calc-result"><p class="sub">Введите данные сделки и нажмите «Рассчитать показатели».</p></div></div></div></div>`}
function calc(){let n=id=>Number($('#'+id).value)||0,p=n('price'),full=n('cost')*(1+n('ved')/100)+n('delivery')+n('install'),min=n('minmargin')/100,disc=n('discount')/100,after=p*(1-disc),profit=after-full,margin=after?profit/after:0,max=1-(full/(1-min))/p,rate=margin<=.2?0:margin<=.3?.03:.05;$('#calc-result').innerHTML=`<div class="card"><span class="label">ГРАНИЧНЫЕ УСЛОВИЯ</span><p>Минимальная цена: <b>${money(full/(1-min))}</b></p><p>Максимальная скидка: <b>${(max*100).toFixed(2)}%</b></p></div><div class="cards" style="grid-template-columns:1fr 1fr"><div class="card"><b>До скидки</b><p>Прибыль: ${money(p-full)}</p><p>Маржа: ${((p-full)/p*100).toFixed(2)}%</p></div><div class="card ${margin<min?'warning':''}"><b>Со скидкой (${(disc*100).toFixed(2)}%)</b><p>Прибыль: ${money(profit)}</p><p>Маржа: ${(margin*100).toFixed(2)}%</p><p>Премия: <b>${(rate*100).toFixed(0)}% · ${money(Math.max(0,profit)*rate)}</b></p></div></div>${margin<min?'<p class="badge danger">Скидка ниже минимальной маржи</p>':'<p class="badge">Скидка допустима</p>'}`}
function references(){return `<div class="wrap"><h1>Заказчики, руководители и организации</h1><p class="sub">Предзаполненные значения и один ручной пример.</p>${banner()}<div class="toolbar"><button class="active">Заказчики</button><button>Руководители</button><button>Организации</button><input placeholder="⌕ Поиск в справочнике"><button class="primary" onclick="addCustomer()">＋ Добавить заказчика</button></div><div class="panel"><table class="table"><thead><tr><th>Статус проектов</th><th>Заказчик</th><th>Руководитель</th><th>Контакты</th></tr></thead><tbody>${state.customers.map(c=>{let rel=state.deals.filter(d=>d.customer===c.name),closed=rel.length&&rel.every(d=>d.status==='Закрыто');return `<tr class="${closed?'closed-row':'active-row'}"><td class="${closed?'status-closed':'status-active'}">● ${closed?'Закрыт':'Активен'}</td><td><b>${c.name}</b></td><td>${c.manager}</td><td>${c.phone}<br><small>${c.email}</small></td></tr>`}).join('')}</tbody></table></div></div>`}
function dataPage(){return `<div class="wrap"><h1>Импорт, экспорт и печать</h1><p class="sub">Перенос и формирование тестовых файлов.</p>${banner()}<div class="grid2"><div class="panel"><div class="wrap"><h3>Импорт CSV</h3><p class="sub">Выберите CSV: в тестовой версии импорт не сохраняется после закрытия вкладки.</p><input type="file" accept=".csv" disabled></div></div><div class="panel"><div class="wrap"><h3>Экспорт</h3><div class="form-grid"><button onclick="exportCSV()">Текущий список CSV</button><button onclick="exportJSON()">JSON-копия</button><button onclick="window.print()">Печать / PDF</button><button disabled>Telegram — скоро</button></div></div></div></div></div>`}
function settings(){return `<div class="wrap"><h1>Настройки и резервная копия</h1><p class="sub">Параметры тестовой локальной сессии.</p>${banner()}<div class="grid2"><div class="panel"><div class="wrap"><h3>Резервная копия JSON</h3><p>Содержит сделки и историю текущей вкладки.</p><button class="primary" onclick="backup()">Создать резервную копию</button></div></div><div class="panel"><div class="wrap"><h3>Восстановление из JSON</h3><input id="restore-file" type="file" accept=".json"><button onclick="restoreJSON()">Восстановить</button></div></div><div class="panel"><div class="wrap"><h3>Демонстрационные данные</h3><p>${state.deals.length} сделок загружено.</p><button onclick="resetDemo()">Загрузить заново</button></div></div><div class="panel"><div class="wrap"><h3>Локальное хранение</h3><p>Данные существуют только в текущей вкладке. После её закрытия они удаляются.</p></div></div></div></div>`}
function columnInfo(){alert('В тестовой версии состав колонок предусмотрен в ТЗ; настройки сохраняются в следующей итерации.')}function download(name,text,type='text/plain'){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();URL.revokeObjectURL(a.href)}function backup(){download('tkp-demo-backup.json',JSON.stringify(state,null,2),'application/json')}function exportJSON(){backup()}function exportCSV(){download('tkp-list.csv','Номер ТКП;Заказчик;Статус;Сумма\n'+state.deals.map(d=>`${d.id};${d.customer};${d.status};${d.amount}`).join('\n'),'text/csv;charset=utf-8')}function resetDemo(){state={page:'Настройки',deals:structuredClone(baseDeals),userDeal:null,period:'Год'};persist();render()}function restoreJSON(){let f=$('#restore-file').files[0];if(!f)return alert('Выберите JSON-файл');let r=new FileReader;r.onload=()=>{try{state=JSON.parse(r.result);persist();render();alert('Данные восстановлены')}catch{alert('Файл имеет неверный формат')}};r.readAsText(f)}
function showDealForm(deal){if(!deal&&state.userDeal)return alert('В демо-сессии можно создать только одну пользовательскую сделку.');let d=deal||{id:`ТКП-2026-${String(state.deals.length+1).padStart(3,'0')}`,title:'',customer:'ООО «Демо Пром»',manager:'Анна Демина',status:'Получен лид',amount:0,contract:'2026-10-01',shipment:'2026-10-15',payment:'2026-10-20',close:'2026-10-30',actualPayment:0,direction:'Промышленность',history:[]};let m=$('#modal');m.innerHTML=`<h2>${deal?'Редактирование сделки':'Новая тестовая сделка'}</h2><form id="deal-form"><div class="form-grid"><div class="field"><label>Номер ТКП</label><input name="id" value="${d.id}" readonly></div><div class="field"><label>Название *</label><input name="title" required value="${d.title}"></div><div class="field"><label>Заказчик *</label><select name="customer">${['ООО «Демо Пром»','ТОО «Демо ЕАЭС»','АО «Демо Инжиниринг»'].map(x=>`<option ${x===d.customer?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Руководитель *</label><select name="manager">${['Анна Демина','Максим Орлов'].map(x=>`<option ${x===d.manager?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Статус *</label><select name="status">${Object.keys(probability).map(x=>`<option ${x===d.status?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Сумма, RUB *</label><input name="amount" type="number" required min="1" value="${d.amount}"></div><div class="field"><label>Договор, план *</label><input name="contract" type="date" required value="${d.contract}"></div><div class="field"><label>Отгрузка, план *</label><input name="shipment" type="date" required value="${d.shipment}"></div><div class="field"><label>Финальный платёж *</label><input name="payment" type="date" required value="${d.payment}"></div><div class="field"><label>Закрытие, план *</label><input name="close" type="date" required value="${d.close}"></div></div><div class="modal-actions"><button type="button" onclick="modal.close()">Отмена</button><button class="primary">Сохранить</button></div></form>`;m.showModal();$('#deal-form').onsubmit=e=>{e.preventDefault();let values=Object.fromEntries(new FormData(e.target));values.amount=Number(values.amount);values.actualPayment=d.actualPayment||0;values.direction=d.direction;values.history=d.history||[];values.history.push({at:new Date().toLocaleString('ru-RU'),action:deal?'Изменение сделки':'Создание сделки'});if(deal){Object.assign(deal,values)}else{state.deals.push(values);state.userDeal=values.id}persist();m.close();render()}}
function openDeal(id){let d=state.deals.find(x=>x.id===id),m=$('#modal');m.innerHTML=`<h2>${d.id}: ${d.title}</h2><p><b>${d.customer}</b> · ${d.manager}</p><p><span class="badge">${d.status}</span> · ${money(d.amount)}</p><p>Договор: ${fmt(d.contract)} · Отгрузка: ${fmt(d.shipment)} · Платёж: ${fmt(d.payment)} · Закрытие: ${fmt(d.close)}</p><h3>История изменений</h3>${d.history.length?`<ul>${d.history.map(x=>`<li>${x.at} — ${x.action}</li>`).join('')}</ul>`:'<p class="sub">Изменений пока нет.</p>'}<div class="modal-actions"><button onclick="markDeal('${d.id}','draft')">Черновик</button><button onclick="markDeal('${d.id}','archive')">Архив</button><button onclick="printOffer('${d.id}')">PDF ТКП</button><button class="primary" onclick="modal.close();showDealForm(state.deals.find(x=>x.id==='${d.id}'))">Редактировать</button></div>`;m.showModal()}
function printOffer(id){let d=state.deals.find(x=>x.id===id);let w=window.open('','_blank');w.document.write(`<html><title>${d.id}</title><body style="font-family:Arial;padding:50px"><h1>Коммерческое предложение</h1><p><b>${d.id}</b> от ${new Date().toLocaleDateString('ru-RU')}</p><h2>${d.title}</h2><p>Заказчик: ${d.customer}</p><table border="1" cellspacing="0" cellpadding="12"><tr><th>Описание</th><th>Сумма, RUB</th></tr><tr><td>${d.title}</td><td>${money(d.amount)}</td></tr></table><p>Условия оплаты: финальный платёж ${fmt(d.payment)}.</p><p>Плановая отгрузка: ${fmt(d.shipment)}.</p><p>Менеджер: ${d.manager}</p><small>Демонстрационный документ без юридически значимой подписи.</small></body></html>`);w.document.close();w.print()}
function render(){nav();let f={'Обзор':overview,'Проекты':projects,'Временная шкала':timeline,'Финансовая сводка':finance,'Калькулятор сделки':calculator,'Справочники':references,'Импорт и экспорт':dataPage,'Настройки':settings}[state.page];$('#page-title').textContent=state.page;$('#view').innerHTML=f();let ps=$('#project-search');if(ps)ps.oninput=e=>{let q=e.target.value.toLowerCase();document.querySelector('.panel .table tbody').innerHTML=dealRows(state.deals.filter(d=>Object.values(d).join(' ').toLowerCase().includes(q)))}}
$('#theme').onclick=()=>{document.body.classList.toggle('theme-dark');$('#theme').textContent=document.body.classList.contains('theme-dark')?'☼ Светлая тема':'◐ Тёмная тема'};$('#new-deal').onclick=()=>showDealForm();$('#global-search').oninput=e=>{if(e.target.value){state.page='Проекты';render();setTimeout(()=>{let x=$('#project-search');x.value=e.target.value;x.dispatchEvent(new Event('input'))})}};render();

function columnInfo(){let labels={id:'Номер ТКП',customer:'Заказчик',manager:'Руководитель',status:'Статус',title:'Описание',direction:'Направление',probability:'Вероятность',amount:'Без НДС',contract:'Договор, план',shipment:'Ближайшее событие',attention:'Внимание'};let m=$('#modal');m.innerHTML=`<h2>Колонки таблицы</h2><p class="sub">Выберите видимость и порядок.</p><div class="column-grid">${Object.entries(labels).map(([k,v])=>`<label><input type="checkbox" ${state.columns.includes(k)?'checked':''} onchange="toggleColumn('${k}',this.checked)"> ${v}　↕</label>`).join('')}</div><div class="modal-actions"><button class="primary" onclick="modal.close();render()">Готово</button></div>`;m.showModal()}
function toggleColumn(key,checked){state.columns=checked?[...state.columns,key]:state.columns.filter(x=>x!==key);persist()}
function addCustomer(){if(state.userCustomer)return alert('В демо-сессии можно добавить только одного заказчика.');let m=$('#modal');m.innerHTML=`<h2>Новый заказчик</h2><form id="customer-form"><div class="form-grid"><div class="field"><label>Название *</label><input name="name" required></div><div class="field"><label>Руководитель *</label><input name="manager" required></div><div class="field"><label>Телефон *</label><input name="phone" required></div><div class="field"><label>E-mail *</label><input name="email" type="email" required></div></div><div class="modal-actions"><button type="button" onclick="modal.close()">Отмена</button><button class="primary">Добавить</button></div></form>`;m.showModal();$('#customer-form').onsubmit=e=>{e.preventDefault();let c=Object.fromEntries(new FormData(e.target));state.customers.push(c);state.userCustomer=c.name;persist();m.close();render()}}

function showDealForm(deal){if(!deal&&state.userDeal)return alert('В демо-сессии можно создать только одну пользовательскую сделку.');let d=deal||{id:'ТКП-2026-003',title:'',customer:state.customers[0].name,manager:state.customers[0].manager,status:'Получен лид',amount:0,contract:'2026-10-01',shipment:'2026-10-15',payment:'2026-10-20',close:'2026-10-30',actualPayment:0,direction:'Промышленность',history:[]};let m=$('#modal');m.innerHTML=`<h2>${deal?'Редактирование сделки':'Новая тестовая сделка'}</h2><form id="deal-form"><div class="form-grid"><div class="field"><label>Номер ТКП</label><input name="id" value="${d.id}" readonly></div><div class="field"><label>Название *</label><input name="title" required value="${d.title}"></div><div class="field"><label>Заказчик *</label><select name="customer">${state.customers.map(c=>`<option ${c.name===d.customer?'selected':''}>${c.name}</option>`).join('')}</select></div><div class="field"><label>Руководитель *</label><select name="manager">${state.customers.map(c=>`<option ${c.manager===d.manager?'selected':''}>${c.manager}</option>`).join('')}</select></div><div class="field"><label>Статус *</label><select name="status">${Object.keys(probability).map(x=>`<option ${x===d.status?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Сумма, RUB *</label><input name="amount" type="number" required min="1" value="${d.amount}"></div><div class="field"><label>Договор, план *</label><input name="contract" type="date" required value="${d.contract}"></div><div class="field"><label>Отгрузка, план *</label><input name="shipment" type="date" required value="${d.shipment}"></div><div class="field"><label>Финальный платёж *</label><input name="payment" type="date" required value="${d.payment}"></div><div class="field"><label>Закрытие, план *</label><input name="close" type="date" required value="${d.close}"></div></div><div class="modal-actions"><button type="button" onclick="modal.close()">Отмена</button><button class="primary">Сохранить</button></div></form>`;m.showModal();$('#deal-form').onsubmit=e=>{e.preventDefault();let values=Object.fromEntries(new FormData(e.target));values.amount=Number(values.amount);values.actualPayment=d.actualPayment||0;values.direction=d.direction;values.history=d.history||[];values.history.push({at:new Date().toLocaleString('ru-RU'),action:deal?'Изменение сделки':'Создание сделки'});if(deal){Object.assign(deal,values)}else{state.deals.push(values);state.userDeal=values.id}persist();m.close();render()}}
function markDeal(id,kind){let d=state.deals.find(x=>x.id===id);d.draft=kind==='draft';d.archived=kind==='archive';d.history.push({at:new Date().toLocaleString('ru-RU'),action:kind==='draft'?'Перемещено в черновики':'Перемещено в архив'});persist();$('#modal').close();state.page='Проекты';state.projectFilter=kind;render()}
function resetDemo(){sessionStorage.removeItem('tkp-demo');location.reload()}

function showDealForm(deal){if(!deal&&state.userDeal)return alert('В демо-сессии можно создать только одну пользовательскую сделку.');let d=deal||{id:'ТКП-2026-003',title:'',customer:state.customers[0].name,manager:state.customers[0].manager,status:'Получен лид',amount:0,contract:'2026-10-01',shipment:'2026-10-15',payment:'2026-10-20',close:'2026-10-30',actualShipment:'',actualPaymentDate:'',actualPayment:0,actualClose:'',direction:'Промышленность',history:[]};let m=$('#modal');m.innerHTML=`<h2>${deal?'Редактирование сделки':'Новая тестовая сделка'}</h2><form id="deal-form"><div class="form-grid"><div class="field"><label>Номер ТКП</label><input name="id" value="${d.id}" readonly></div><div class="field"><label>Название *</label><input name="title" required value="${d.title}"></div><div class="field"><label>Заказчик *</label><select name="customer">${state.customers.map(c=>`<option ${c.name===d.customer?'selected':''}>${c.name}</option>`).join('')}</select></div><div class="field"><label>Руководитель *</label><select name="manager">${state.customers.map(c=>`<option ${c.manager===d.manager?'selected':''}>${c.manager}</option>`).join('')}</select></div><div class="field"><label>Статус *</label><select name="status">${Object.keys(probability).map(x=>`<option ${x===d.status?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Сумма, RUB *</label><input name="amount" type="number" required min="1" value="${d.amount}"></div><div class="field"><label>Договор, план *</label><input name="contract" type="date" required value="${d.contract}"></div><div class="field"><label>Отгрузка, план *</label><input name="shipment" type="date" required value="${d.shipment}"></div><div class="field"><label>Финальный платёж, план *</label><input name="payment" type="date" required value="${d.payment}"></div><div class="field"><label>Закрытие, план *</label><input name="close" type="date" required value="${d.close}"></div></div><div class="fact-inputs"><b>Фактические показатели</b><div class="form-grid"><div class="field"><label>Фактическая отгрузка</label><input name="actualShipment" type="date" value="${d.actualShipment||''}"></div><div class="field"><label>Фактическая оплата</label><input name="actualPaymentDate" type="date" value="${d.actualPaymentDate||''}"></div><div class="field"><label>Получено фактически, RUB</label><input name="actualPayment" type="number" min="0" value="${d.actualPayment||0}"></div><div class="field"><label>Фактическое закрытие</label><input name="actualClose" type="date" value="${d.actualClose||''}"></div></div></div><div class="modal-actions"><button type="button" onclick="modal.close()">Отмена</button><button class="primary">Сохранить</button></div></form>`;m.showModal();$('#deal-form').onsubmit=e=>{e.preventDefault();let values=Object.fromEntries(new FormData(e.target));values.amount=Number(values.amount);values.actualPayment=Number(values.actualPayment);values.direction=d.direction;values.history=d.history||[];values.history.push({at:new Date().toLocaleString('ru-RU'),action:deal?'Изменены плановые/фактические показатели':'Создание сделки'});if(deal){Object.assign(deal,values)}else{state.deals.push(values);state.userDeal=values.id}persist();m.close();render()}}

function references(){let managers=[...new Map(state.customers.map(c=>[c.manager,c])).values()];return `<div class="wrap"><h1>Заказчики и менеджеры</h1><p class="sub">Менеджеры — руководители сделок и участники отчёта эффективности.</p>${banner()}<div class="toolbar"><button class="active" onclick="state.refTab='customers';render()">Заказчики</button><button onclick="state.refTab='managers';render()">Менеджеры</button><button disabled>Организации</button><input placeholder="⌕ Поиск в справочнике"><button class="primary" onclick="addCustomer()">＋ Добавить заказчика</button></div><div class="panel"><table class="table"><thead><tr><th>${state.refTab==='managers'?'Менеджер':'Статус проектов'}</th><th>${state.refTab==='managers'?'Заказчики':'Заказчик'}</th><th>Контакты</th></tr></thead><tbody>${(state.refTab==='managers'?managers:state.customers).map(c=>{let rel=state.deals.filter(d=>d.customer===c.name),closed=rel.length&&rel.every(d=>d.status==='Закрыто');return state.refTab==='managers'?`<tr><td><b>${c.manager}</b></td><td>${state.customers.filter(x=>x.manager===c.manager).map(x=>x.name).join(', ')}</td><td>${c.phone}<br><small>${c.email}</small></td></tr>`:`<tr class="${closed?'closed-row':'active-row'}"><td class="${closed?'status-closed':'status-active'}">● ${closed?'Закрыт':'Активен'}</td><td><b>${c.name}</b><br><small>${c.manager}</small></td><td>${c.phone}<br><small>${c.email}</small></td></tr>`}).join('')}</tbody></table></div></div>`}

function monthly(key,month,actual=false){return state.deals.filter(d=>d[key]?.slice(5,7)===String(month).padStart(2,'0')).reduce((s,d)=>s+(actual?(key==='actualShipment'?d.amount:d.actualPayment||0):d.amount),0)}
function chartTip(e,month){let p=monthly('shipment',month),f=monthly('actualShipment',month,true),cp=monthly('payment',month),cf=monthly('actualPaymentDate',month,true),t=$('#chart-tip');t.innerHTML=`<b>${['январь','февраль','март','апрель','май','июнь','июль','август','сентябрь','октябрь','ноябрь','декабрь'][month-1]} 2026</b><br>Выручка: план ${money(p)} / факт ${money(f)}<br>Поток: план ${money(cp)} / факт ${money(cf)}`;t.style.display='block';t.style.left=(e.offsetX+20)+'px';t.style.top='30px'}function hideTip(){$('#chart-tip').style.display='none'}
function finance(){let months=['Янв','Фев','Мар','Апр','Май','Июн','Июл','Авг','Сен','Окт','Ноя','Дек'],max=Math.max(...months.flatMap((_,i)=>[monthly('shipment',i+1),monthly('actualShipment',i+1,true),monthly('payment',i+1),monthly('actualPaymentDate',i+1,true)]),1);return `<div class="wrap"><h1>Финансовая сводка: план и факт</h1><p class="sub">Выручка формируется по отгрузке, денежный поток — по оплате.</p>${banner()}${period()}${kpis()}<div class="panel"><h3>Динамика по месяцам</h3><p class="sub" style="padding:0 18px">Наведите курсор на месяц для детальной расшифровки.</p><div class="finance-chart" id="finance-chart"><div id="chart-tip" class="chart-tip"></div>${months.map((x,i)=>{let m=i+1;return `<div class="month-group" data-month="${x}" onmouseenter="chartTip(event,${m})" onmouseleave="hideTip()"><i class="metric-bar revenue-plan" style="height:${monthly('shipment',m)/max*210}px" title="Выручка, план"></i><i class="metric-bar revenue-fact" style="height:${monthly('actualShipment',m,true)/max*210}px" title="Выручка, факт"></i><i class="metric-bar cash-plan" style="height:${monthly('payment',m)/max*210}px" title="Поток, план"></i><i class="metric-bar cash-fact" style="height:${monthly('actualPaymentDate',m,true)/max*210}px" title="Поток, факт"></i></div>`}).join('')}</div><div class="legend"><i class="revenue-plan"></i>Выручка, план <i class="revenue-fact"></i>Выручка, факт <i class="cash-plan"></i>Поток, план <i class="cash-fact"></i>Поток, факт</div></div><div class="panel"><h3>Помесячная сводка</h3><table class="table"><thead><tr><th>Месяц</th><th>Выручка, план</th><th>Выручка, факт</th><th>Денежный поток, план</th><th>Денежный поток, факт</th></tr></thead><tbody>${months.map((x,i)=>`<tr><td><b>${x} 2026</b></td><td>${money(monthly('shipment',i+1))}</td><td>${money(monthly('actualShipment',i+1,true))}</td><td>${money(monthly('payment',i+1))}</td><td>${money(monthly('actualPaymentDate',i+1,true))}</td></tr>`).join('')}</tbody></table></div><h2>Отчёты</h2><div class="report-cards"><div class="card"><b>Воронка</b><p>${Object.keys(probability).map(s=>`${s}: ${state.deals.filter(d=>d.status===s).length}`).join('<br>')}</p></div><div class="card"><b>Просроченная дебиторка</b><strong>${money(state.deals.filter(d=>overdue(d.payment)).reduce((s,d)=>s+Math.max(0,d.amount-(d.actualPayment||0)),0))}</strong><p class="sub">Неоплаченные платежи с прошедшей плановой датой</p></div><div class="card"><b>Эффективность менеджеров</b>${[...new Set(state.deals.map(d=>d.manager))].map(m=>`<p>${m}: <b>${money(state.deals.filter(d=>d.manager===m).reduce((s,d)=>s+d.amount,0))}</b></p>`).join('')}</div></div></div>`}

function asOf(){return state.asOfMode?(state.asOfDate||'2026-09-19'):'9999-12-31'}function onOrBefore(date){return !!date&&date<=asOf()}function overdue(date){return !!state.asOfMode&&!!date&&date<asOf()}function period(){return `<div class="period"><b>ПЕРИОД ПЛАНИРОВАНИЯ</b><span>01 янв. 2026 — 31 дек. 2026</span><button class="${!state.asOfMode?'active':''}" onclick="state.asOfMode=false;render()">Текущий год</button><button class="${state.asOfMode?'active':''}" onclick="state.asOfMode=true;render()">На дату</button><span class="date-filter ${state.asOfMode?'':'hidden'}">Дата <input type="date" value="${state.asOfDate||'2026-09-19'}" onchange="state.asOfDate=this.value;render()"></span></div>`}
function factMonthly(key,month){return state.deals.filter(d=>d[key]?.slice(5,7)===String(month).padStart(2,'0')&&onOrBefore(d[key])).reduce((s,d)=>s+(key==='actualShipment'?d.amount:d.actualPayment||0),0)}function planMonthly(key,month){return state.deals.filter(d=>d[key]?.slice(5,7)===String(month).padStart(2,'0')&&onOrBefore(d[key])).reduce((s,d)=>s+d.amount,0)}
function comboTip(e,month,type){let p=planMonthly(type==='revenue'?'shipment':'payment',month),f=factMonthly(type==='revenue'?'actualShipment':'actualPaymentDate',month),t=$('#chart-tip');t.innerHTML=`<b>${['январь','февраль','март','апрель','май','июнь','июль','август','сентябрь','октябрь','ноябрь','декабрь'][month-1]} 2026</b><br>План: ${money(p)}<br>Факт: ${money(f)}`;t.style.display='block';t.style.left=(e.offsetX+20)+'px';t.style.top='20px'}
function comboChart(title,type){let months=['Янв','Фев','Мар','Апр','Май','Июн','Июл','Авг','Сен','Окт','Ноя','Дек'],pk=type==='revenue'?'shipment':'payment',fk=type==='revenue'?'actualShipment':'actualPaymentDate',plans=months.map((_,i)=>planMonthly(pk,i+1)),facts=months.map((_,i)=>factMonthly(fk,i+1)),max=Math.max(...plans,...facts,1),points=plans.map((v,i)=>`${i/11*100},${100-v/max*100}`).join(' ');return `<div class="panel ${type==='cash'?'cash-combo':''}"><h3>${title}</h3><p class="sub" style="padding:0 18px">План — линия, факт — столбцы. Наведите на месяц для расшифровки.</p><div class="combo-chart"><div id="chart-tip" class="chart-tip"></div>${months.map((x,i)=>`<div class="combo-month" data-month="${x}" onmouseenter="comboTip(event,${i+1},'${type}')" onmouseleave="hideTip()"><i class="combo-bar" style="height:${facts[i]/max*190}px"></i></div>`).join('')}<svg class="plan-svg" preserveAspectRatio="none" viewBox="0 0 100 100"><polyline points="${points}" vector-effect="non-scaling-stroke"/></svg></div><div class="legend"><i class="${type==='revenue'?'revenue-fact':'cash-fact'}"></i>Факт — столбцы <i class="${type==='revenue'?'cash-plan':'revenue-plan'}"></i>План — линия</div></div>`}
function finance(){let months=['Янв','Фев','Мар','Апр','Май','Июн','Июл','Авг','Сен','Окт','Ноя','Дек'],debt=state.deals.filter(d=>overdue(d.payment)&&onOrBefore(d.payment)).reduce((s,d)=>s+Math.max(0,d.amount-(d.actualPayment||0)),0),concluded=state.deals.filter(d=>['Подписано','В работе','Закрыто'].includes(d.status)&&onOrBefore(d.contract)).reduce((s,d)=>s+d.amount,0),executed=state.deals.filter(d=>d.actualClose&&onOrBefore(d.actualClose)).reduce((s,d)=>s+d.amount,0);return `<div class="wrap"><h1>Финансовая сводка: план и факт</h1><p class="sub">Выручка — по отгрузке, денежный поток — по оплате.</p>${banner()}${period()}${kpis()}${comboChart('Выручка по месяцам','revenue')}${comboChart('Денежный поток по месяцам','cash')}<div class="panel"><h3>Помесячная сводка</h3><table class="table"><thead><tr><th>Месяц</th><th>Выручка, план</th><th>Выручка, факт</th><th>Денежный поток, план</th><th>Денежный поток, факт</th></tr></thead><tbody>${months.map((x,i)=>`<tr><td><b>${x} 2026</b></td><td>${money(planMonthly('shipment',i+1))}</td><td>${money(factMonthly('actualShipment',i+1))}</td><td>${money(planMonthly('payment',i+1))}</td><td>${money(factMonthly('actualPaymentDate',i+1))}</td></tr>`).join('')}</tbody></table></div><h2>Отчёты</h2><div class="report-cards"><div class="card"><b>Воронка</b><p>${Object.keys(probability).map(s=>`${s}: ${state.deals.filter(d=>d.status===s).length}`).join('<br>')}</p></div><div class="card"><b>Просроченная дебиторка на ${fmt(asOf())}</b><strong>${money(debt)}</strong><p class="sub">План платежа минус факт оплаты на выбранную дату</p></div><div class="card"><b>Эффективность менеджеров</b><p>Заключённые договоры: <b>${money(concluded)}</b></p><p>Исполненные договоры: <b>${money(executed)}</b></p></div></div></div>`}

function openDeal(id){let d=state.deals.find(x=>x.id===id),m=$('#modal'),debt=overdue(d.payment)?Math.max(0,d.amount-(d.actualPayment||0)):0;m.innerHTML=`<h2>${d.id}: ${d.title}</h2><p><b>${d.customer}</b> · ${d.manager}</p><p><span class="badge">${d.status}</span> · ${money(d.amount)}</p><p>Плановый платёж: ${fmt(d.payment)} · ${money(d.amount)}<br>Факт оплаты: ${fmt(d.actualPaymentDate)} · ${money(d.actualPayment)}</p>${state.asOfMode?`<p class="${debt?'badge danger':'badge'}">Дебиторка на ${fmt(asOf())}: ${money(debt)}</p>`:'<p class="sub">Включите «На дату» в периоде для контроля дебиторки.</p>'}<p>Договор: ${fmt(d.contract)} · Отгрузка: ${fmt(d.shipment)} · Закрытие: ${fmt(d.close)}</p><h3>История изменений</h3>${d.history.length?`<ul>${d.history.map(x=>`<li>${x.at} — ${x.action}</li>`).join('')}</ul>`:'<p class="sub">Изменений пока нет.</p>'}<div class="modal-actions"><button onclick="markDeal('${d.id}','draft')">Черновик</button><button onclick="markDeal('${d.id}','archive')">Архив</button><button onclick="printOffer('${d.id}')">PDF ТКП</button><button class="primary" onclick="modal.close();showDealForm(state.deals.find(x=>x.id==='${d.id}'))">Редактировать</button></div>`;m.showModal()}
function comboTip(e,month,type){let p=planMonthly(type==='revenue'?'shipment':'payment',month),f=factMonthly(type==='revenue'?'actualShipment':'actualPaymentDate',month),t=e.currentTarget.closest('.combo-chart').querySelector('.chart-tip');t.innerHTML=`<b>${['январь','февраль','март','апрель','май','июнь','июль','август','сентябрь','октябрь','ноябрь','декабрь'][month-1]} 2026</b><br>План: ${money(p)}<br>Факт: ${money(f)}`;t.style.display='block';t.style.left=(e.offsetX+20)+'px';t.style.top='20px'}function hideTip(){document.querySelectorAll('.chart-tip').forEach(x=>x.style.display='none')}

