function deviation(d){return (d.actualShipment&&d.actualShipment!==d.shipment)||(d.actualPaymentDate&&d.actualPaymentDate!==d.payment)||(d.actualPayment&&d.actualPayment!==d.amount)||isOverdue(d)}
