function timeline(){let managers=[...new Set(state.deals.map(d=>d.manager))],statuses=Object.keys(probability),ds=state.deals.filter(d=>(!state.timelineManager||d.manager===state.timelineManager)&&(!state.timelineStatus||d.status===state.timelineStatus)),months=['Сентябрь','Октябрь','Ноябрь','Декабрь'],cell=(d,m)=>[['contract','Договор'],['payment','Финальный платёж'],['shipment','Отгрузка'],['close','Закрытие']].filter(([k])=>d[k]?.slice(5,7)===m).map(([k,n])=>`<div class="event ${overdue(d[k])?'overdue':''}">${n}<br>${fmt(d[k])}</div>`).join('');return `<div class="wrap"><h1>Месячная временная шкала</h1><p class="sub">Проекты по ключевым плановым датам.</p>${banner()}${period()}<div class="toolbar"><input placeholder="⌕ Номер, заказчик, описание"><select onchange="state.timelineManager=this.value;render()"><option value="">Все менеджеры</option>${managers.map(x=>`<option ${x===state.timelineManager?'selected':''}>${x}</option>`).join('')}</select><select onchange="state.timelineStatus=this.value;render()"><option value="">Все статусы</option>${statuses.map(x=>`<option ${x===state.timelineStatus?'selected':''}>${x}</option>`).join('')}</select><button>‹</button><button>Сегодня</button><button>›</button></div><div class="panel"><div class="timeline"><b>ПРОЕКТ И ОПИСАНИЕ</b>${months.map(x=>`<b>${x} 2026</b>`).join('')}${ds.map(d=>`<div><b>${d.id}</b><br><small>${d.title}</small></div>${[9,10,11,12].map(m=>`<div>${cell(d,String(m).padStart(2,'0'))}</div>`).join('')}`).join('')}</div></div></div>`}

