function dataPage(){return `<div class="wrap"><h1>Импорт, экспорт и печать</h1><div class="blocked-note">Функции заблокированы в тестовой версии.</div><div class="grid2 blocked"><div class="panel"><div class="wrap"><h3>Импорт CSV</h3><input type="file" disabled></div></div><div class="panel"><div class="wrap"><h3>Экспорт</h3><button disabled>Текущий список CSV</button> <button disabled>Книга XLSX</button> <button disabled>Печать / PDF</button></div></div></div></div>`}

function choosePeriod(mode){state.pendingPeriodMode=mode;state.pendingAsOfMode=false;render()}function chooseAsOf(){state.pendingAsOfMode=true;render()}function applyPeriod(){state.periodMode=state.pendingPeriodMode||state.periodMode;state.asOfMode=!!state.pendingAsOfMode;state.asOfDate=state.pendingAsOfDate||state.asOfDate;state.dateFrom=state.pendingDateFrom||state.dateFrom;state.dateTo=state.pendingDateTo||state.dateTo;persist();render()}
function period(){let modes=['Текущий месяц','Квартал','Текущий год','Следующий год','Свой период'],mode=state.pendingPeriodMode||state.periodMode||'Текущий год',asof=state.pendingAsOfMode??state.asOfMode,from=state.pendingDateFrom||state.dateFrom||'2026-01-01',to=state.pendingDateTo||state.dateTo||'2026-12-31',date=state.pendingAsOfDate||state.asOfDate||'2026-09-19';return `<div class="period"><div><small>ПЕРИОД ПЛАНИРОВАНИЯ</small><br><b>${state.asOfMode?`На дату ${fmt(state.asOfDate)}`:state.periodMode==='Свой период'?`${fmt(state.dateFrom||from)} — ${fmt(state.dateTo||to)}`:'01 янв. 2026 г. — 31 дек. 2026 г.'}</b></div>${modes.map(x=>`<button class="${!asof&&mode===x?'active':''}" onclick="choosePeriod('${x}')">${x}</button>`).join('')}<button class="${asof?'active':''}" onclick="chooseAsOf()">На дату</button><span class="date-filter ${mode==='Свой период'||asof?'':'hidden'}">${asof?'Дата':'С даты'} <input type="date" value="${asof?date:from}" onchange="${asof?'state.pendingAsOfDate=this.value':'state.pendingDateFrom=this.value'}">${asof?'':`По дату <input type="date" value="${to}" onchange="state.pendingDateTo=this.value">`}</span><button class="primary" onclick="applyPeriod()">Применить</button></div>`}
