function comboChart(title,type){let months=['Янв','Фев','Мар','Апр','Май','Июн','Июл','Авг','Сен','Окт','Ноя','Дек'],pk=type==='revenue'?'shipment':'payment',fk=type==='revenue'?'actualShipment':'actualPaymentDate',plans=months.map((_,i)=>planMonthly(pk,i+1)),facts=months.map((_,i)=>factMonthly(fk,i+1)),max=Math.max(...plans,...facts,1),points=plans.map((v,i)=>`${50+i*100},${210-v/max*190}`).join(' '),mln=x=>`${(x/1000000).toLocaleString('ru-RU',{maximumFractionDigits:1})} млн ₽`,ticks=[max,max/2,0];return `<div class="panel ${type==='cash'?'cash-combo':''}"><h3>${title}</h3><p class="sub" style="padding:0 18px">План — линия, факт — столбцы. Наведите на месяц для расшифровки.</p><div class="combo-chart"><div class="chart-tip"></div>${months.map((x,i)=>`<div class="combo-month" data-month="${x}" onmouseenter="comboTip(event,${i+1},'${type}')" onmouseleave="hideTip()"><i class="combo-bar" style="height:${facts[i]/max*190}px"></i></div>`).join('')}<svg class="plan-svg" width="100%" height="100%" viewBox="0 0 1200 220" preserveAspectRatio="none"><polyline points="${points}"/></svg><div class="axis-labels">${ticks.map(x=>`<span>${mln(x)}</span>`).join('')}</div></div><div class="legend"><i class="${type==='revenue'?'revenue-fact':'cash-fact'}"></i>Факт — столбцы <i class="${type==='revenue'?'cash-plan':'revenue-plan'}"></i>План — линия</div></div>`}

function kpiDeals(kind){let ds=state.deals;if(kind==='active')return ds.filter(d=>d.status!=='Закрыто');if(kind==='forecast')return ds.filter(d=>['Создано ТКП','Передано на согласование'].includes(d.status));if(kind==='revenue')return ds.filter(d=>['Подписано','В работе'].includes(d.status));return ds}
function kpis(){let active=kpiDeals('active'),forecast=kpiDeals('forecast'),revenue=kpiDeals('revenue'),cash=kpiDeals('cash'),forecastValue=forecast.reduce((s,d)=>s+d.amount*probability[d.status],0),revenueValue=revenue.reduce((s,d)=>s+d.amount,0),cashPlan=cash.reduce((s,d)=>s+d.amount,0),cashFact=cash.reduce((s,d)=>s+(d.actualPayment||0),0),card=(key,label,value,note)=>`<div class="card"><span class="label">${label}</span><strong>${value}</strong><small>${note}</small><div class="modal-actions"><button onclick="showKpiDetails('${key}')">Расшифровать</button></div></div>`;return `<div class="cards">${card('active','Активные проекты',active.length,'Все проекты в работе')}${card('forecast','Прогноз договоров',money(forecastValue),'Создано ТКП и на согласовании')}${card('revenue','Плановая выручка',money(revenueValue),'Подписано и в работе')}${card('cash','Денежный поток',`План ${money(cashPlan)}`,`Факт ${money(cashFact)}`)}</div>`}
function showKpiDetails(kind){let ds=kpiDeals(kind),title={active:'Активные проекты',forecast:'Прогноз договоров',revenue:'Плановая выручка',cash:'Денежный поток'}[kind],m=$('#modal');m.innerHTML=`<h2>${title}: расшифровка</h2><div class="panel"><table class="table"><thead><tr><th>ТКП</th><th>Заказчик</th><th>Описание</th><th>Статус</th><th>Платёж</th><th>%</th><th>Дата</th><th>Исходная сумма</th><th>Факт</th></tr></thead><tbody>${ds.map(d=>`<tr><td>${d.id}</td><td>${d.customer}</td><td>${d.title}</td><td>${d.status}</td><td>${fmt(d.payment)}</td><td>${Math.round(probability[d.status]*100)}%</td><td>${fmt(kind==='revenue'?d.shipment:kind==='forecast'?d.contract:d.payment)}</td><td>${money(d.amount)}</td><td>${money(d.actualPayment||0)}</td></tr>`).join('')}</tbody></table></div><div class="modal-actions"><button class="primary" onclick="modal.close()">Закрыть</button></div>`;m.showModal()}

function kpis(){let active=kpiDeals('active'),forecast=kpiDeals('forecast'),revenue=kpiDeals('revenue'),cash=kpiDeals('cash'),forecastValue=forecast.reduce((s,d)=>s+d.amount*probability[d.status],0),revenueValue=revenue.reduce((s,d)=>s+d.amount,0),cashPlan=cash.reduce((s,d)=>s+d.amount,0),cashFact=cash.reduce((s,d)=>s+(d.actualPayment||0),0),card=(key,label,icon,value,note)=>`<article class="card kpi-card"><div class="kpi-head"><span>${label}</span><span class="kpi-icon" aria-hidden="true">${icon}</span></div><strong>${value}</strong><small class="kpi-note">${note}</small><div class="modal-actions"><button type="button" onclick="showKpiDetails('${key}')">Расшифровать</button></div></article>`;return `<div class="cards">${card('active','Активные проекты','▣',active.length,'Все проекты в работе')}${card('forecast','Прогноз договоров','✎',money(forecastValue),'Создано ТКП и на согласовании')}${card('revenue','Плановая выручка','⌂',money(revenueValue),'Подписано и в работе')}${card('cash','Денежный поток','▤',`План ${money(cashPlan)} · Факт ${money(cashFact)}`,'Ожидаемые и фактические поступления')}</div>`}

// Финальная логика периода и компактные KPI. Текущий месяц всегда вычисляется от даты браузера.
function iso(d){return d.toISOString().slice(0,10)}
function monthRange(){let now=new Date(),m=now.getMonth()+1,y=now.getFullYear(),mode=state.periodMode||'Текущий год',from=state.dateFrom,to=state.dateTo;if(mode==='Текущий месяц'){from=iso(new Date(y,m-1,1));to=iso(new Date(y,m,0))}else if(mode==='Квартал'){let q=Math.floor((m-1)/3)*3;from=iso(new Date(y,q,1));to=iso(new Date(y,q+3,0))}else if(mode==='Текущий год'){from=`${y}-01-01`;to=`${y}-12-31`}else if(mode==='Следующий год'){from=`${y+1}-01-01`;to=`${y+1}-12-31`}return {from:from||`${y}-01-01`,to:to||`${y}-12-31`}}
function inPeriod(date){let r=monthRange(),end=state.asOfMode?(state.asOfDate||iso(new Date())):r.to;return !!date&&date>=r.from&&date<=end}
function choosePeriod(mode){state.pendingPeriodMode=mode;state.pendingAsOfMode=false;render()}
function chooseAsOf(){state.pendingAsOfMode=true;state.pendingAsOfDate=state.pendingAsOfDate||iso(new Date());render()}
function applyPeriod(){state.periodMode=state.pendingPeriodMode||state.periodMode||'Текущий год';state.asOfMode=!!state.pendingAsOfMode;state.asOfDate=state.pendingAsOfDate||state.asOfDate||iso(new Date());state.dateFrom=state.pendingDateFrom||state.dateFrom;state.dateTo=state.pendingDateTo||state.dateTo;persist();render()}
function period(){let modes=['Текущий месяц','Квартал','Текущий год','Следующий год','Свой период'],mode=state.pendingPeriodMode||state.periodMode||'Текущий год',asof=state.pendingAsOfMode??state.asOfMode,r=monthRange(),from=state.pendingDateFrom||r.from,to=state.pendingDateTo||r.to,date=state.pendingAsOfDate||state.asOfDate||iso(new Date());return `<div class="period"><div><small>ПЕРИОД ПЛАНИРОВАНИЯ</small><br><b>${asof?`На дату ${fmt(date)}`:`${fmt(r.from)} — ${fmt(r.to)}`}</b></div>${modes.map(x=>`<button class="${!asof&&mode===x?'active':''}" onclick="choosePeriod('${x}')">${x}</button>`).join('')}<button class="${asof?'active':''}" onclick="chooseAsOf()">На дату</button><span class="date-filter ${mode==='Свой период'||asof?'':'hidden'}">${asof?'Дата':'С даты'} <input type="date" value="${asof?date:from}" onchange="${asof?'state.pendingAsOfDate=this.value':'state.pendingDateFrom=this.value'}">${asof?'':`По дату <input type="date" value="${to}" onchange="state.pendingDateTo=this.value">`}</span><button class="primary" onclick="applyPeriod()">Применить</button></div>`}
function attentionDebts(){let cutoff=state.asOfMode?(state.asOfDate||iso(new Date())):monthRange().to;return state.deals.filter(d=>d.payment&&d.payment<=cutoff&&(d.actualPayment||0)<d.amount)}
function kpis(){let active=kpiDeals('active'),forecast=kpiDeals('forecast'),revenue=kpiDeals('revenue'),cash=kpiDeals('cash'),forecastValue=forecast.reduce((s,d)=>s+d.amount*probability[d.status],0),revenueValue=revenue.reduce((s,d)=>s+d.amount,0),cashPlan=cash.reduce((s,d)=>s+d.amount,0),cashFact=cash.reduce((s,d)=>s+(d.actualPayment||0),0),card=(key,label,icon,value,note)=>`<article class="card kpi-card"><div class="kpi-head"><span>${label}</span><button class="kpi-icon kpi-action" aria-label="Расшифровать: ${label}" title="Расшифровать" onclick="showKpiDetails('${key}')">${icon}</button></div><strong>${value}</strong><small class="kpi-note">${note}</small></article>`;return `<div class="cards">${card('active','Активные проекты','▣',active.length,'Все проекты в работе')}${card('forecast','Прогноз договоров','✎',money(forecastValue),'Создано ТКП и на согласовании')}${card('revenue','Плановая выручка','⌂',money(revenueValue),'Подписано и в работе')}${card('cash','Денежный поток','▤',`План ${money(cashPlan)} · Факт ${money(cashFact)}`,'Ожидаемые и фактические поступления')}</div>`}
function overview(){let alerts=attentionDebts();return `<div class="wrap"><h1>Обзор</h1><p class="sub">Ключевые показатели и ближайшие события.</p>${banner()}${period()}${kpis()}<div class="grid2"><div>${dealTable(state.deals.filter(x=>x.status!=='Закрыто'))}</div><div class="panel"><h3>Требует внимания</h3><ul class="kpi-list">${alerts.length?alerts.map(d=>`<li>⚠ <b>${d.id}</b><br><small>Задолженность: ${money(d.amount-(d.actualPayment||0))}; план оплаты ${fmt(d.payment)}</small></li>`).join(''):'<li>Нет отклонений плана и факта по задолженности</li>'}</ul></div></div></div>`}
function chartData(type){let labels=['Янв','Фев','Мар','Апр','Май','Июн','Июл','Авг','Сен','Окт','Ноя','Дек'],pk=type==='revenue'?'shipment':'payment',fk=type==='revenue'?'actualShipment':'actualPaymentDate',r=monthRange(),year=Number(r.from.slice(0,4)),start=new Date(r.from+'T00:00:00').getMonth(),end=new Date(r.to+'T00:00:00').getMonth(),count=(Number(r.to.slice(0,4))-year)*12+end-start+1;return Array.from({length:Math.max(1,Math.min(count,12))},(_,n)=>{let month=(start+n)%12+1,yr=year+Math.floor((start+n)/12),prefix=`${yr}-${String(month).padStart(2,'0')}`,plan=state.deals.filter(d=>d[pk]?.startsWith(prefix)&&inPeriod(d[pk])).reduce((s,d)=>s+d.amount,0),fact=state.deals.filter(d=>d[fk]?.startsWith(prefix)&&inPeriod(d[fk])).reduce((s,d)=>s+(type==='revenue'?d.amount:(d.actualPayment||0)),0);return {label:labels[month-1],plan,fact}})}
function comboChart(title,type){let rows=chartData(type),max=Math.max(...rows.flatMap(x=>[x.plan,x.fact]),1),points=rows.map((v,i)=>`${50+i*(1100/Math.max(rows.length-1,1))},${210-v.plan/max*180}`).join(' '),mln=x=>`${(x/1e6).toLocaleString('ru-RU',{maximumFractionDigits:1})} млн ₽`;return `<div class="panel"><h3>${title}</h3><p class="sub" style="padding:0 18px">План — линия, факт — столбцы. Суммы указаны слева, в млн ₽.</p><div class="combo-chart"><div class="axis-labels"><span>${mln(max)}</span><span>${mln(max/2)}</span><span>0 млн ₽</span></div><div class="chart-tip"></div>${rows.map((x,i)=>`<div class="combo-month" data-month="${x.label}" onmouseenter="comboTip(event,${i+1},'${type}')" onmouseleave="hideTip()"><i class="combo-bar" style="height:${x.fact/max*190}px"></i></div>`).join('')}<svg class="plan-svg" width="100%" height="100%" viewBox="0 0 1200 220" preserveAspectRatio="none"><polyline points="${points}"/></svg></div><div class="legend"><i class="${type==='revenue'?'revenue-fact':'cash-fact'}"></i>Факт — столбцы <i class="${type==='revenue'?'cash-plan':'revenue-plan'}"></i>План — линия</div></div>`}
function finance(){let months=chartData('revenue'),debts=attentionDebts(),debt=debts.reduce((s,d)=>s+d.amount-(d.actualPayment||0),0),mgr=[...new Set(state.deals.map(d=>d.manager))];return `<div class="wrap"><h1>Финансовая сводка: план и факт</h1><p class="sub">Выручка — по отгрузке, денежный поток — по оплате.</p>${banner()}${period()}${kpis()}${comboChart('Выручка по месяцам','revenue')}${comboChart('Денежный поток по месяцам','cash')}<div class="panel"><h3>Помесячная сводка</h3><table class="table"><thead><tr><th>Месяц</th><th>Выручка, план</th><th>Выручка, факт</th><th>Денежный поток, план</th><th>Денежный поток, факт</th></tr></thead><tbody>${months.map((x,i)=>{let c=chartData('cash')[i];return `<tr><td><b>${x.label}</b></td><td>${money(x.plan)}</td><td>${money(x.fact)}</td><td>${money(c.plan)}</td><td>${money(c.fact)}</td></tr>`}).join('')}</tbody></table></div><h2>Отчёты</h2><div class="report-cards"><div class="card"><b>Воронка</b><p>${Object.keys(probability).map(s=>`${s}: ${state.deals.filter(d=>d.status===s).length}`).join('<br>')}</p></div><div class="card"><b>Просроченная дебиторка</b><strong>${money(debt)}</strong>${mgr.map(m=>{let v=debts.filter(d=>d.manager===m).reduce((s,d)=>s+d.amount-(d.actualPayment||0),0);return v?`<p>${m}: <b>${money(v)}</b></p>`:''}).join('')}<p class="sub">Разница планового и фактического поступления</p></div><div class="card"><b>Эффективность менеджеров</b>${mgr.map(m=>{let a=state.deals.filter(d=>d.manager===m),c=a.filter(d=>['Подписано','В работе','Закрыто'].includes(d.status)).reduce((s,d)=>s+d.amount,0),e=a.reduce((s,d)=>s+(d.actualPayment||0),0);return `<p><b>${m}</b><br>Заключено: ${money(c)}<br>Исполнено: ${money(e)}</p>`}).join('')}</div></div></div>`}
function references(){let managers=[...new Map(state.customers.map(c=>[c.manager,c])).values()],isMgr=state.refTab==='managers',items=isMgr?managers:state.customers;return `<div class="wrap"><h1>Заказчики и менеджеры</h1><p class="sub">Записи можно редактировать; изменения применяются к будущему выбору в проектах.</p>${banner()}<div class="toolbar"><button class="${!isMgr?'active':''}" onclick="state.refTab='customers';render()">Заказчики</button><button class="${isMgr?'active':''}" onclick="state.refTab='managers';render()">Менеджеры</button><button disabled>Организации</button><input placeholder="⌕ Поиск в справочнике"><button class="primary" onclick="addCustomer()">＋ Добавить заказчика</button></div><div class="panel"><table class="table"><thead><tr><th>${isMgr?'Менеджер':'Статус проектов'}</th><th>${isMgr?'Заказчики':'Заказчик'}</th><th>Контакты</th><th></th></tr></thead><tbody>${items.map(c=>{let idx=state.customers.indexOf(c),rel=state.deals.filter(d=>d.customer===c.name),closed=rel.length&&rel.every(d=>d.status==='Закрыто');return isMgr?`<tr><td><b>${c.manager}</b></td><td>${state.customers.filter(x=>x.manager===c.manager).map(x=>x.name).join(', ')}</td><td>${c.phone}<br><small>${c.email}</small></td><td><button onclick="editReference(${idx})">Изменить</button></td></tr>`:`<tr class="${closed?'closed-row':'active-row'}"><td class="${closed?'status-closed':'status-active'}">● ${closed?'Закрыт':'Активен'}</td><td><b>${c.name}</b><br><small>${c.manager}</small></td><td>${c.phone}<br><small>${c.email}</small></td><td><button onclick="editReference(${idx})">Изменить</button></td></tr>`}).join('')}</tbody></table></div></div>`}
function editReference(index){let c=state.customers[index],m=$('#modal');m.innerHTML=`<h2>Редактирование справочника</h2><form id="ref-form"><div class="form-grid"><div class="field"><label>Заказчик</label><input name="name" value="${c.name}" required></div><div class="field"><label>Менеджер</label><input name="manager" value="${c.manager}" required></div><div class="field"><label>Телефон</label><input name="phone" value="${c.phone}" required></div><div class="field"><label>E-mail</label><input name="email" value="${c.email}" type="email" required></div></div><div class="modal-actions"><button type="button" onclick="modal.close()">Отмена</button><button class="primary">Сохранить</button></div></form>`;m.showModal();$('#ref-form').onsubmit=e=>{e.preventDefault();let before={...c},next=Object.fromEntries(new FormData(e.target));state.deals.forEach(d=>{if(d.customer===before.name)d.customer=next.name;if(d.manager===before.manager)d.manager=next.manager});Object.assign(c,next);persist();m.close();render()}}
function settings(){return `<div class="wrap"><h1>Настройки и резервная копия</h1><div class="blocked-note">Настройки, резервное копирование и восстановление заблокированы в тестовой версии.</div><div class="grid2 blocked"><div class="panel"><div class="wrap"><h3>Резервная копия JSON</h3><button disabled>Создать резервную копию</button></div></div><div class="panel"><div class="wrap"><h3>Восстановление из JSON</h3><input type="file" disabled></div></div></div></div>`}
